{"code":"import solver

def trial(s):
    r = solver.trial(network_id="snem-sa-2000", operation="load_scale", scale=s,
                     observation="bus_voltage", observation_id=2008, max_iter=50)
    return r

target = 0.9422
tol = 0.002

# s=0.905 gives 0.94237, closest so far. Try higher values.
for s in [0.906, 0.907, 0.908, 0.909, 0.91]:
    r = trial(s)
    if r['data']['metric_valid']:
        v = r['data']['metric']
        diff = abs(v - target)
        print(f"s={s}: V={v}, diff={diff}")
        if diff < 0.000167:
            print(f"Better: s={s}")"}

